/**
 * The call QA scenarios: the 20 of brief §62, and 26 more from the voice QA
 * pass (2026-09-28: dialect and ASR variants, several objections in one
 * call, a gatekeeper, a bad line, privacy, the price asked first, a quote
 * for two services, a lead who says yes to everything, silence, hostility,
 * a call-back at a bad time, voicemail and phone menus). Each is a scripted
 * prospect plus
 * what a correct call looks like: the disposition, the tools that must (and
 * must not) run, whether the closing attribution is spoken, and the time
 * budget (the route's own maximum unless stated).
 */

import type { NextBestAction } from "../../../src/lib/qualification-intelligence/types.ts";
import { PROVIDER_MAX_DURATION_SEC } from "../../../src/lib/voice/time-governor.ts";
import type { Scenario } from "./simulator.ts";

function ask(rendering: string, dimension = "TEAM_SIZE"): NextBestAction {
  return {
    current_goal: "B_BOOK_MEETING",
    intent_state: "MEDIUM",
    intent_score: 55,
    known_dimensions: [],
    unknown_required_dimensions: [],
    next_action: "ASK",
    question_intent: { key: `${dimension}.COUNT`, dimension, purpose: "QUALIFY", question_id: null, wording_family: dimension.toLowerCase(), rendering },
    reason: "One gap left",
    rule: "R9",
    expected_information_gain: 0.5,
    qualification_score: 50,
    qualification_completeness: 0.5,
    engine_verdict: "PENDING",
    confidence: 0.8,
    handover_reason: null,
    assist_reason: null,
    resume_at: null,
    suppress: false,
    model_call_required: true,
  } as unknown as NextBestAction;
}

const TEAM = ask("How many people are on the team that would use it?");
const EMAIL = ask("What is the best email for the invite?", "EMAIL");
const BUDGET = ask("Roughly what budget have you set aside?", "BUDGET");
/** Said after a stop, a refusal or a vulnerable person: a pitch. */
const PITCH = /website|team|book|price|enquir|slot|morning|afternoon/i;

